            { interval: "60,000 km", timeLimit: "5 years", task: "Transfer Case Fluid (M xDrive)", details: "CRITICAL: Drain and refill transfer case fluid and RESET adaptations via software to prevent AWD binding under the massive torque.", parts: ["0.7L DTF-1"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
            { interval: "50,000 km", timeLimit: "5 years", task: "Rear Active M Differential Fluids", details: "CRITICAL: Extract and carefully refill. The rear torque-vectoring diff requires specific friction modifiers in the outer chambers.", parts: ["1.0L SAF-XJ", "1.2L SAF-Carbon Mod"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
            { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush and bleed the massive M-Compound brakes thoroughly.", parts: ["1.0L DOT 4 LV"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" },
            { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "Drain and refill the main engine circuit, charge-air circuit, AND the highly sensitive High-Voltage Battery cooling circuit.", parts: ["25.0L HT-12 Coolant"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }
