          { partName: "Intake Boot", category: "Intake", oem: { brand: "BMW Genuine", code: "13711739574", approxPrice: "45 EUR" }, crossRef: { brand: "Febi Bilstein", code: "33100", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=13711739574", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=13711739574" }, note: "Connects MAF to throttle body. Prone to cracking." }
