            { interval: "80,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings (FCAB)", details: "Replace the lollipops at the rear of the front control arms to cure steering slop and heavy braking shimmy.", parts: ["Lemförder / Powerflex"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" },
            { interval: "100,000 km", timeLimit: "10 years", task: "Driveshaft Guibo (Flex Disc)", details: "Inspect and replace the rubber flex disc if severe cracking or tearing is visible to prevent driveline vibrations.", parts: ["Febi / Lemförder Guibo"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" },
            { interval: "Immediately", timeLimit: "Unlimited", task: "Z3 Trunk Floor Inspection", details: "CRITICAL: Inspect the spot welds in the trunk floor above the differential mount. If popping or tearing is visible, structural reinforcement welding is mandatory.", parts: ["Welding / Plates"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "800 - 1,500 EUR" }
