            { interval: "150,000 km", timeLimit: "12 years", task: "Timing Chain Guides", details: "CRITICAL: Remove the front timing cover and replace the massive plastic U-guides. If they shatter, the chain will jump timing and destroy the valves.", parts: ["OEM Guide Kit", "Gaskets"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "2,000 - 3,000 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Double VANOS Rebuild & Solenoid Soldering", details: "CRITICAL: Remove the VANOS units, replace the O-rings, and professionally reflow the solder joints on the solenoid boards to cure hesitation and codes.", parts: ["Beisan Kit", "O-rings"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "800 - 1,200 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Cooling System Overhaul", details: "CRITICAL: Preventatively replace the water pump, thermostat (located in the V-valley), radiator, and expansion tank before they explode.", parts: ["Pump", "T-Stat", "Radiator", "Tank"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "600 EUR" },
            { interval: "60,000 km", timeLimit: "6 years", task: "Spark Plug Replacement", details: "Replace the 4-prong platinum spark plugs.", parts: ["8x NGK BKR6EQUP"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "80 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "MAF Sensor Replacement", details: "Proactively replace both Mass Air Flow sensors to cure subtle hesitations and restore sharp throttle response.", parts: ["2x Bosch MAFs"], importance: "High", laborDifficulty: "Easy", estimatedCost: "300 EUR" }
