            { interval: "2 Years", timeLimit: "2 years", task: "Brake & Clutch Fluid Flush", details: "Flush and bleed the DOT 4 fluid. The clutch slave cylinder shares the fluid reservoir.", parts: ["1.0L DOT 4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" },
            { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "CRITICAL: Regularly flush the cooling system to prevent corrosion of the aluminum block and cylinder head.", parts: ["10.5L BMW G48 Blue"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }
