            { interval: "100,000 km", timeLimit: "8 years", task: "Cooling System Overhaul", details: "CRITICAL: Preventatively replace the water pump, thermostat housing, radiator, expansion tank, and upper/lower hoses before they explode.", parts: ["Pump", "T-Stat", "Radiator", "Tank", "Hoses"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Dual VANOS Seal Rebuild", details: "CRITICAL: Remove the VANOS unit and replace the hardened factory Buna O-rings with upgraded Viton seals to restore low-end torque.", parts: ["Beisan Seal Kit", "VCG"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "80 EUR (Parts) / 300 EUR (Labor)" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber profile gasket behind the oil filter housing. This is a massive source of oil leaks that coats the front of the engine.", parts: ["Genuine BMW Gasket"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "25 EUR (Part) / 200 EUR (Labor)" },
            { interval: "As Needed", timeLimit: "Unlimited", task: "CCV System Replacement", details: "If the engine develops a whistling sound, extreme oil consumption, or 'mayo' under the oil cap, replace the crankcase vent valve and all 4 brittle plastic hoses.", parts: ["Vaico CCV Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "120 EUR" },
            { interval: "100,000 km", timeLimit: "Unlimited", task: "DISA Valve Rebuild", details: "CRITICAL: Remove the DISA valve and install an aluminum flap and titanium pin to prevent the factory plastic pin from destroying the engine.", parts: ["GAS Rebuild Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "90 EUR" },
            { interval: "60,000 km", timeLimit: "6 years", task: "Spark Plug Replacement", details: "Replace the standard 4-prong platinum spark plugs.", parts: ["6x NGK BKR6EQUP"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "60 EUR" }
