            { interval: "80,000 km", timeLimit: "8 years", task: "Automatic Transmission Fluid", details: "Drain and refill the ATF fluid, and replace the filter. Ignore lifetime fill claims to preserve the ZF 6-speed.", parts: ["9.0L ZF Lifeguard 6", "Filter Kit"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "200 EUR" },
            { interval: "80,000 km", timeLimit: "8 years", task: "Rear Differential Oil", details: "Drain and refill the rear differential.", parts: ["1.0L 75W-90 Synthetic"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 EUR" },
            { interval: "2 Years", timeLimit: "2 years", task: "Brake & Clutch Fluid Flush", details: "Flush and bleed the DOT 4 fluid. The clutch slave cylinder shares the fluid reservoir.", parts: ["1.0L DOT 4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" },
            { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "Regularly flush the cooling system to prevent corrosion. Must run the electric water pump bleeding procedure.", parts: ["7.5L BMW G48 Blue"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }
