      { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber profile gaskets behind the oil filter housing. This prevents oil from dripping onto the belt and destroying the engine.", parts: ["Elring Gaskets"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace the drive belt and tensioner. If the belt snaps, it can be sucked into the engine block.", parts: ["Conti Belt Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "120 EUR" },
      { interval: "100,000 km", timeLimit: "Unlimited", task: "DISA Valve Rebuild", details: "CRITICAL: Remove the two DISA valves on the intake manifold and install aluminum flaps and titanium pins to prevent engine ingestion.", parts: ["GAS Rebuild Kit"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "150 EUR" },
      { interval: "As Needed", timeLimit: "Unlimited", task: "VANOS Solenoid Cleaning/Replacement", details: "If the engine idles roughly or hesitates, remove and clean the two VANOS solenoids on the front of the block. Replace if cleaning fails.", parts: ["Genuine BMW Solenoids"], importance: "High", laborDifficulty: "Easy", estimatedCost: "150 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Spark Plug & Coil Replacement", details: "Replace the iridium spark plugs. Replace ignition coils preventatively to cure misfires.", parts: ["6x NGK Plugs", "6x Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "200 EUR" }
