      { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filter", details: "Replace the panel filter in the airbox.", parts: ["Mann Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" },
      { interval: "60,000 km", timeLimit: "6 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Mahle Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "30 EUR" }
