      { interval: "50,000 km", timeLimit: "5 years", task: "Valve Clearance Adjustment", details: "CRITICAL: Remove the valve cover and manually measure and adjust the clearance of all 24 valves using specialized shims. Failure to do so burns valves.", parts: ["Shim Kit", "VCG"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "500 EUR" },
      { interval: "100,000 km", timeLimit: "Unlimited", task: "High-Pressure VANOS Rebuild", details: "CRITICAL: Remove the complex VANOS unit, replace the hardened solenoid seals, and upgrade the internal exhaust hub and oil pump disc.", parts: ["Beisan Kit", "Gaskets"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1000 EUR" },
      { interval: "60,000 km", timeLimit: "6 years", task: "Cooling System Overhaul", details: "CRITICAL: Preventatively replace the water pump, thermostat, radiator, and expansion tank before they explode and warp the cylinder head.", parts: ["Pump", "T-Stat", "Radiator", "Tank"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "500 EUR" },
      { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plug Replacement", details: "Replace the M-specific spark plugs to ensure a clean burn at high RPM.", parts: ["6x NGK DCPR8EKP"], importance: "High", laborDifficulty: "Easy", estimatedCost: "80 EUR" }
