      { interval: "80,000 km", timeLimit: "8 years", task: "Rear Differential Oil", details: "Drain and refill the rear differential.", parts: ["0.8L 75W-90 Synthetic"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "50 EUR" },
      { interval: "2 Years", timeLimit: "2 years", task: "Brake & Clutch Fluid Flush", details: "Flush and bleed the DOT 4 LV fluid. The clutch slave cylinder shares the fluid reservoir.", parts: ["1.0L DOT 4 LV"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "50 EUR" },
      { interval: "60,000 km", timeLimit: "4 years", task: "Engine Coolant Flush", details: "Regularly flush the cooling system. Must run the electric water pump automated bleeding procedure.", parts: ["7.0L BMW G48 Blue"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }
