      { interval: "60,000 km", timeLimit: "Unlimited", task: "Intake Valve Walnut Blasting", details: "CRITICAL: Remove the intake manifold and blast the intake valves with walnut shells to remove severe carbon buildup, restoring horsepower.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 - 500 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Electric Water Pump & Thermostat", details: "CRITICAL: Preventatively replace the electric water pump before it fails electronically and strands the vehicle.", parts: ["Pierburg Pump", "Mahle T-Stat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" },
      { interval: "100,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket (OFHG)", details: "CRITICAL: Replace the rubber profile gaskets to prevent oil from dripping onto the belt and causing fatal belt ingestion.", parts: ["Elring Gaskets"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" },
      { interval: "60,000 km", timeLimit: "Unlimited", task: "Spark Plug & Coil Replacement", details: "The N54 eats spark plugs and ignition coils rapidly. Replace preventatively to cure high-boost misfires. If tuned, replace plugs every 20,000 km.", parts: ["6x NGK Plugs", "6x Bosch Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "250 EUR" },
      { interval: "100,000 km", timeLimit: "Unlimited", task: "Valve Cover Replacement", details: "The plastic valve cover warps and leaks oil, and the integrated PCV valve fails. The entire cover must be replaced.", parts: ["Elring Valve Cover Assm"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "400 EUR" }
